export function createStudentReadingList({e,api,link}){async function page(p){const q=Object.fromEntries(['classId','search','status','offset'].filter(k=>p.get(k)).map(k=>[k,p.get(k)])),d=await api('student-reading?'+new URLSearchParams(q)),base={view:'reading',...q};return '<div class="learning-section-title"><h2>My reading</h2><span>'+d.summary.pending+' to confirm · '+d.summary.updated+' updated</span></div><p>Class guides from all your subjects. Open a material, read it, then confirm on its page.</p><form data-student-reading-filters class="community-filters"><input type="hidden" name="view" value="reading"><label>Class<select name="classId" aria-label="Reading class"><option value="">All my classes</option>'+d.classes.map(c=>'<option value="'+e(c.id)+'" '+(c.id===q.classId?'selected':'')+'>'+e(c.name)+'</option>').join('')+'</select></label><label>Show<select name="status" aria-label="Reading status">'+[['pending','To confirm'],['updated','Updated · read again'],['confirmed','Confirmed'],['all','All materials']].map(([k,t])=>'<option value="'+k+'" '+(k===(q.status||'pending')?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Find<input name="search" maxlength="120" aria-label="Find reading material" placeholder="Title, topic or class" value="'+e(q.search||'')+'"></label><button class="btn">Find reading</button>'+link('Clear filters',{view:'reading'})+'</form><p>'+d.total+' matching '+(d.total===1?'material':'materials')+'</p><div class="vle-grid">'+d.rows.map(r=>'<article class="vle-panel"><small>'+e(r.className)+' · '+e(r.topic)+'</small><h3>'+link(r.title,{class:r.classId,tab:'apps',material:r.id})+'</h3><p>'+(r.status==='confirmed'?'Reading confirmed':r.status==='updated'?'Updated · please read again':'Reading to confirm')+'</p>'+link('Open material →',{class:r.classId,tab:'apps',material:r.id})+'</article>').join('')+'</div>'+(!d.total?'<p class="learning-empty">'+(q.search?'No materials match these filters.':(q.status||'pending')==='pending'?'You have no reading left to confirm in this view.':'No materials match this view.')+'</p>':'')+'<div class="vle-actions">'+(d.offset?link('← Previous',{...base,offset:d.offset-d.limit}):'')+(d.offset+d.limit<d.total?link('Next →',{...base,offset:d.offset+d.limit}):'')+'</div>';}
 function bind(root){root.querySelector('[data-student-reading-filters]')?.addEventListener('submit',ev=>{ev.preventDefault();location.hash='/classroom?'+new URLSearchParams([...new FormData(ev.currentTarget)].filter(([,v])=>v));});}return{page,bind};}
